/**
 * DataSources 组件 v11 — 补充国际标准 + 法规链接
 *
 * 升级要点（v11）：
 *   - 新增「国际标准」数据源卡片（FDA GRAS / EFSA / JFSA / Codex）
 *   - 国标卡片增加法规原文链接
 *   - 卡片底部展示可点击的标准链接
 */
import { useState } from 'react';
import { Reveal } from '../shared/Reveal';
import { cn } from '@/lib/utils';
import {
  dataSources, type DataSource,
} from '../data/dataSources';
import { Database, Network, Shield, Scale, FlaskConical, RefreshCw, Globe, ExternalLink } from 'lucide-react';

// ── 聚合统计 ──────────────────────────────────────────────────────
const SYNC_STATUS   = '实时同步';

// ── 状态指示点 ──────────────────────────────────────────────────────
function StatusDot({ status }: { status: DataSource['status'] }) {
  const cfg = {
    online:  { color: 'var(--color-primary-700, #047857)', label: '在线' },
    syncing: { color: 'var(--color-secondary-700, #1d4ed8)', label: '同步中' },
    update:  { color: 'var(--color-warning-700, #b45309)', label: '已更新' },
  };
  const c = cfg[status];
  return (
    <div className="flex items-center gap-1.5" title={c.label}>
      <span
        className="lp-data-card-status-dot"
        style={{ background: c.color, boxShadow: `0 0 0 2px ${c.color}25` }}
      />
      <span className="lp-data-card-subtitle" style={{ color: c.color }}>{c.label}</span>
    </div>
  );
}

// ── 单张卡片 ────────────────────────────────────────────────────────
function DataSourceCard({ data, index }: { data: DataSource; index: number }) {
  const iconMap: Record<string, React.ReactNode> = {
    'flask-conical': <FlaskConical size={14} />,
    'dna':           <Database size={14} />,
    'network':       <Network size={14} />,
    'shield-check':  <Shield size={14} />,
    'scale':         <Scale size={14} />,
    'globe':         <Globe size={14} />,
  };

  const isPrimary = index < 2; // 前两张为主数据源，更大更显眼

  return (
    <Reveal delay={`lp-reveal-delay-${(index % 3) + 1}`}>
      <div
        className={cn('lp-data-card', isPrimary && 'lp-data-card--primary')}
        style={{
          '--card-accent-color': data.color,
          '--card-hover-border': data.colorBorder,
        } as React.CSSProperties}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
      >
        {/* 左侧彩色竖条 */}
        <div className="lp-data-card-accent" style={{ background: data.color }} />

        {/* 头部：图标 + 名称 + 状态 */}
        <div className="lp-data-card-header">
          <div className="flex items-start gap-2.5 min-w-0">
            <div
              className="lp-data-card-icon"
              style={{ background: data.colorLight, color: data.color, borderColor: data.colorBorder }}
            >
              {iconMap[data.icon] ?? <Database size={14} />}
            </div>
            <div className="lp-data-card-title-group">
              <div className="lp-data-card-name">{data.name}</div>
              <div className="lp-data-card-subtitle" style={{ color: data.colorText || data.color }}>{data.subtitle}</div>
            </div>
          </div>
          <StatusDot status={data.status} />
        </div>

        {/* 描述 */}
        <div className="lp-data-card-body">
          <p className="lp-data-card-desc">{data.desc}</p>
          {/* 能力标签 */}
          <div className="lp-data-card-features">
            {data.features.map(f => (
              <span
                key={f}
                className="lp-data-card-feature"
                style={{
                  background: data.colorLight,
                  color: data.colorText || data.color,
                  border: `1px solid ${data.colorBorder}`,
                }}
              >
                {f}
              </span>
            ))}
          </div>
        </div>

        {/* 法规原文链接（P0 对比度 + 44px 热区修复） */}
        {data.links && data.links.length > 0 && (
          <div className="lp-data-card-links">
            {data.links.map(link => (
              <a
                key={link.label}
                href={link.url}
                target="_blank"
                rel="noreferrer"
                className="lp-data-card-link"
                style={{ color: data.colorText || data.color }}
              >
                <ExternalLink size={12} className="shrink-0" />
                <span className="truncate">{link.label}</span>
              </a>
            ))}
          </div>
        )}

        {/* 底部：统计 + 连接状态 */}
        <div className="lp-data-card-footer">
          <div className="lp-data-card-stat">
            <span className="lp-data-card-stat-value" style={{ color: data.colorText || data.color }}>{data.stat}</span>
            <span className="lp-data-card-stat-label">{data.statLabel}</span>
          </div>
          <span
            className="lp-data-card-connect"
            style={{ color: data.colorText || data.color, background: data.colorLight, border: `1px solid ${data.colorBorder}` }}
          >
            <RefreshCw size={8} className={data.status === 'syncing' ? 'animate-spin' : ''} />
            连接就绪
          </span>
        </div>
      </div>
    </Reveal>
  );
}

// ── 主组件 ──────────────────────────────────────────────────────────
export default function DataSources() {
  return (
    <section id="data-sources" className="py-16 lg:py-20" style={{ background: 'var(--bg-canvas, #f8fafc)', borderTop: '1px solid var(--color-neutral-200, #e2e8f0)' }}>
      <div className="max-w-6xl mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8">

        {/* 标题区 */}
        <Reveal>
          <div className="lp-data-section-header">
            <div className="lp-data-section-title-group">
              <span className="lp-section-tag block mb-2">数据底座</span>
              <h2 className="lp-h2 mb-1">6 大数据源 · 128,000+ 知识节点</h2>
              <p className="lp-data-section-desc">
                覆盖中药材、活性肽、知识图谱、法规标准、国际标准五大维度，支持跨库联合查询与实时同步。
              </p>
            </div>
            <span className="lp-caption shrink-0 hidden sm:block" style={{ color: 'var(--color-neutral-600, #475569)' }}>
              最后更新：刚刚
            </span>
          </div>
        </Reveal>

        {/* 聚合统计横幅 */}
        <Reveal>
          <div className="lp-data-panel mb-6" style={{ background: 'var(--color-neutral-900, #0f172a)' }}>
            {[
              { value: '6',  label: '数据源',  color: 'var(--color-success-600, #6ee7b7)' },
              { value: '38K+', label: '知识实体', color: 'var(--color-secondary-300, #93c5fd)' },
              { value: '128K', label: '图谱节点', color: 'var(--color-accent-300, #c4b5fd)' },
              { value: SYNC_STATUS, label: '同步状态', color: 'var(--color-neutral-300, #cbd5e1)' },
            ].map((s, i) => (
              <div key={i} className="flex-1 flex items-center gap-0">
                {i > 0 && <div className="lp-data-panel-divider mr-4" />}
                <div className="lp-data-panel-stat">
                  <span className="lp-data-panel-value" style={{ color: s.color }}>{s.value}</span>
                  <span className="lp-data-panel-label">{s.label}</span>
                </div>
              </div>
            ))}
          </div>
        </Reveal>

        {/* 主数据源（前2张） */}
        <div className="lp-data-primary-row mb-2.5">
          {dataSources.slice(0, 2).map((ds, i) => (
            <DataSourceCard key={ds.id} data={ds} index={i} />
          ))}
        </div>

        {/* 次数据源（后4张） */}
        <div className="lp-data-secondary-row">
          {dataSources.slice(2).map((ds, i) => (
            <DataSourceCard key={ds.id} data={ds} index={i + 2} />
          ))}
        </div>

      </div>
    </section>
  );
}

import { useState, useMemo, useCallback, memo } from 'react'
import {
  Plus,
  Pencil,
  Trash2,
  ChevronRight,
  ChevronDown,
  FolderOpen,
  Folder,
  Users,
  Loader2,
  X,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { Modal } from '@/components/ui/Modal'
import { useToast } from '@/components/ui/Toast'
import type { Member, Team, Role } from '@/hooks/useOrganizationDetail'

interface TeamsTabProps {
  organizationId: number
  members: Member[]
  teams: Team[]
  memberCount: number
  teamCount: number
  organization?: { storageUsed: number; storageLimit: number; apiCalls?: number; plan: string }
  onInvite?: (email: string, role?: Role) => Promise<void>
  onRemoveMember?: (memberId: number) => Promise<void>
  onUpdateRole?: (memberId: number, role: Role) => Promise<void>
  onCreateTeam?: (data: Partial<Team>) => Promise<Team>
  onUpdateTeam?: (teamId: number, data: Partial<Team>) => Promise<void>
  onDeleteTeam?: (teamId: number) => Promise<void>
  onRefresh?: () => void
}

function getMemberById(members: Member[], memberId: number): Member | undefined {
  return members.find((m) => m.userId === memberId)
}

function MiniAvatar({ name, size = 24 }: { name: string; size?: number }) {
  return (
    <div
      className={cn(
        'rounded-[var(--radius-pill)] bg-gradient-to-br from-secondary-400 to-accent-500 flex items-center justify-center text-white text-xs font-medium border-2 border-white dark:border-neutral-800 shrink-0 -ml-1 first:ml-0',
      )}
      style={{ width: size, height: size }}
      title={name}
    >
      {name?.charAt(0)?.toUpperCase()}
    </div>
  )
}

interface TeamTreeNodeProps {
  team: Team
  allTeams: Team[]
  members: Member[]
  depth: number
  expandedTeams: Set<number>
  selectedTeamId: number | null
  onToggleExpand: (id: number) => void
  onSelectTeam: (id: number | null) => void
  onEdit: (team: Team) => void
  onDelete: (team: Team) => void
  onCreateChild: (parentId: number) => void
}

const TeamTreeNode = memo(function TeamTreeNode({
  team,
  allTeams,
  members,
  depth,
  expandedTeams,
  selectedTeamId,
  onToggleExpand,
  onSelectTeam,
  onEdit,
  onDelete,
  onCreateChild,
}: TeamTreeNodeProps) {
  const childTeams = useMemo(() => allTeams.filter(t => t.slug.startsWith(team.slug + '/')), [allTeams, team.slug])
  const isExpanded = expandedTeams.has(team.id)
  const isSelected = selectedTeamId === team.id
  const hasChildren = childTeams.length > 0
  const teamMembers = team.memberIds.map((id) => getMemberById(members, id)).filter(Boolean) as Member[]

  return (
    <div role="treeitem" aria-expanded={hasChildren ? isExpanded : undefined}>
      <div
        className={cn(
          'flex items-center gap-2 px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] cursor-pointer transition-all group',
          isSelected
            ? 'bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20 border border-[var(--color-secondary-border)] dark:border-[var(--color-secondary)]'
            : 'hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)]/30 border border-transparent',
          depth > 0 && 'ml-6',
        )}
        style={{ paddingLeft: `${depth * 24 + 12}px` }}
        onClick={() => onSelectTeam(isSelected ? null : team.id)}
      >
        {/* Expand/Collapse Toggle */}
        <button
          onClick={(e) => {
            e.stopPropagation()
            if (hasChildren) onToggleExpand(team.id)
          }}
          className={cn(
            'w-5 h-5 flex items-center justify-center rounded transition-colors shrink-0',
            hasChildren ? 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--text-secondary)]' : 'invisible',
          )}
          aria-label={isExpanded ? '收起' : '展开'}
        >
          {hasChildren ? (
            isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />
          ) : (
            <span className="w-1 h-1 rounded-[var(--radius-pill)] bg-neutral-300 dark:bg-[var(--border-color)]" />
          )}
        </button>

        {/* Icon */}
        {isExpanded || !hasChildren ? (
          <FolderOpen className="w-4.5 h-4.5 text-[var(--color-secondary-text)]0 shrink-0" />
        ) : (
          <Folder className="w-4.5 h-4.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] shrink-0" />
        )}

        {/* Name */}
        <span className="flex-1 font-medium text-sm text-[var(--text-primary)] truncate min-w-0">
          {team.name}
        </span>

        {/* Member Count & Avatars */}
        <div className="flex items-center gap-2 shrink-0">
          {teamMembers.length > 0 && (
            <div className="flex items-center">
              {teamMembers.slice(0, 4).map((m) => (
                <MiniAvatar key={m.userId} name={m.displayName} size={22} />
              ))}
              {teamMembers.length > 4 && (
                <span className="ml-1 text-xs text-[var(--text-muted)] w-5 h-5 rounded-[var(--radius-pill)] bg-[var(--bg-tertiary)] flex items-center justify-center -ml-1 border-2 border-white dark:border-neutral-800">
                  +{teamMembers.length - 4}
                </span>
              )}
            </div>
          )}
          <span className="inline-flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            <Users className="w-3.5 h-3.5" />
            {team.memberIds.length}
          </span>

          {/* Action Buttons */}
          <div className="opacity-0 group-hover:opacity-100 flex items-center gap-0.5 transition-opacity">
            <button
              onClick={(e) => { e.stopPropagation(); onCreateChild(team.id) }}
              className="p-1 rounded text-[var(--text-muted)] hover:text-[var(--color-secondary-text)] hover:bg-[var(--color-secondary-container)] dark:hover:bg-[var(--color-secondary-container)]/20"
              title="添加子团队"
              aria-label={`在 ${team.name} 下创建子团队`}
            >
              <Plus className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={(e) => { e.stopPropagation(); onEdit(team) }}
              className="p-1 rounded text-[var(--text-muted)] hover:text-[var(--color-primary-text)] hover:bg-[var(--color-primary-container)] dark:hover:bg-[var(--color-primary-container)]/20"
              title="编辑团队"
              aria-label={`编辑 ${team.name}`}
            >
              <Pencil className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={(e) => { e.stopPropagation(); onDelete(team) }}
              className="p-1 rounded text-[var(--text-muted)] hover:text-[var(--color-error-text)] hover:bg-[var(--color-error-container)] dark:hover:bg-[var(--color-error-container)]/20"
              title="删除团队"
              aria-label={`删除 ${team.name}`}
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </div>

      {/* Children */}
      {hasChildren && isExpanded && (
        <div role="group">
          {childTeams.map((child) => (
            <TeamTreeNode
              key={child.id}
              team={child}
              allTeams={allTeams}
              members={members}
              depth={depth + 1}
              expandedTeams={expandedTeams}
              selectedTeamId={selectedTeamId}
              onToggleExpand={onToggleExpand}
              onSelectTeam={onSelectTeam}
              onEdit={onEdit}
              onDelete={onDelete}
              onCreateChild={onCreateChild}
            />
          ))}
        </div>
      )}
    </div>
  )
})

const TeamsTab = memo(({ teams, members, teamCount, onCreateTeam, onUpdateTeam, onDeleteTeam }: TeamsTabProps) => {
  const toast = useToast()
  const [expandedTeams, setExpandedTeams] = useState<Set<number>>(new Set())
  const [selectedTeamId, setSelectedTeamId] = useState<number | null>(null)

  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [parentTeamId, setParentTeamId] = useState<number | null>(null)
  const [editingTeam, setEditingTeam] = useState<Team | null>(null)
  const [deletingTeam, setDeletingTeam] = useState<Team | null>(null)

  const [formName, setFormName] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [submitting, setSubmitting] = useState(false)

  const rootTeams = useMemo(() => teams.filter((t) => !t.slug.includes('/')), [teams])

  const selectedTeamMembers = useMemo(() => {
    if (!selectedTeamId) return []
    const team = teams.find((t) => t.id === selectedTeamId)
    if (!team) return []
    return team.memberIds.map((id) => getMemberById(members, id)).filter(Boolean) as Member[]
  }, [selectedTeamId, teams, members])

  const toggleExpand = useCallback((id: number) => {
    setExpandedTeams((prev) => {
      const next = new Set(prev)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }, [])

  const handleCreate = useCallback(async () => {
    if (!formName.trim()) {
      toast.warning('请输入团队名称')
      return
    }
    setSubmitting(true)
    try {
      await onCreateTeam?.({
        name: formName.trim(),
        description: formDescription.trim() || undefined,
      })
      toast.success('团队创建成功')
      setShowCreateModal(false)
      setFormName('')
      setFormDescription('')
      setParentTeamId(null)
    } catch (err: any) {
      toast.error(err.message || '创建失败')
    } finally {
      setSubmitting(false)
    }
  }, [formName, formDescription, onCreateTeam, toast])

  const handleUpdate = useCallback(async () => {
    if (!editingTeam || !formName.trim()) return
    setSubmitting(true)
    try {
      await onUpdateTeam?.(editingTeam.id, {
        name: formName.trim(),
        description: formDescription.trim() || undefined,
      })
      toast.success('团队信息已更新')
      setShowEditModal(false)
      setEditingTeam(null)
      setFormName('')
      setFormDescription('')
    } catch (err: any) {
      toast.error(err.message || '更新失败')
    } finally {
      setSubmitting(false)
    }
  }, [editingTeam, formName, formDescription, onUpdateTeam, toast])

  const handleDelete = useCallback(async () => {
    if (!deletingTeam) return
    setSubmitting(true)
    try {
      await onDeleteTeam?.(deletingTeam.id)
      toast.success(`团队 "${deletingTeam.name}" 已删除`)
      setShowDeleteModal(false)
      setDeletingTeam(null)
      if (selectedTeamId === deletingTeam.id) setSelectedTeamId(null)
    } catch (err: any) {
      toast.error(err.message || '删除失败')
    } finally {
      setSubmitting(false)
    }
  }, [deletingTeam, onDeleteTeam, toast, selectedTeamId])

  const openCreateModal = useCallback((parentId?: number | null) => {
    setParentTeamId(parentId ?? null)
    setFormName('')
    setFormDescription('')
    setShowCreateModal(true)
  }, [])

  const openEditModal = useCallback((team: Team) => {
    setEditingTeam(team)
    setFormName(team.name)
    setFormDescription(team.description || '')
    setShowEditModal(true)
  }, [])

  const openDeleteModal = useCallback((team: Team) => {
    setDeletingTeam(team)
    setShowDeleteModal(true)
  }, [])

  return (
    <div className="p-8 space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">团队管理</h2>
          <p className="text-sm text-[var(--text-muted)] mt-0.5">共 {teamCount} 个团队</p>
        </div>
        <button
          onClick={() => openCreateModal(null)}
          className="inline-flex items-center gap-2 px-[var(--space-apple-md)] py-2.5 bg-secondary-container text-secondary-main rounded-[var(--radius-Apple-sm)] hover:bg-secondary-container transition-colors text-sm font-medium shadow-sm shadow-secondary-500/25"
        >
          <Plus className="w-4 h-4" />
          创建团队
        </button>
      </div>

      {/* Main Layout: Tree + Detail Panel */}
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
        {/* Tree View */}
        <div className="lg:col-span-3 bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-5" role="tree" aria-label="团队树形结构">
          {rootTeams.length === 0 ? (
            <div className="py-12 text-center">
              <Folder className="w-12 h-12 mx-auto text-[var(--text-muted)] dark:text-[var(--text-muted)] mb-[var(--space-apple-sm)]" />
              <p className="text-[var(--text-muted)] font-medium">暂无团队</p>
              <p className="text-sm text-[var(--text-muted)] mt-1">点击上方按钮创建第一个团队</p>
            </div>
          ) : (
            <div className="space-y-0.5">
              {rootTeams.map((team) => (
                <TeamTreeNode
                  key={team.id}
                  team={team}
                  allTeams={teams}
                  members={members}
                  depth={0}
                  expandedTeams={expandedTeams}
                  selectedTeamId={selectedTeamId}
                  onToggleExpand={toggleExpand}
                  onSelectTeam={setSelectedTeamId}
                  onEdit={openEditModal}
                  onDelete={openDeleteModal}
                  onCreateChild={openCreateModal}
                />
              ))}
            </div>
          )}
        </div>

        {/* Detail Panel */}
        <div className="lg:col-span-2 space-y-[var(--space-apple-md)]">
          {/* Selected Team Info */}
          {selectedTeamId ? (
            <div className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-5 animate-fade-in">
              <div className="flex items-start justify-between mb-[var(--space-apple-md)]">
                <div>
                  <h3 className="font-semibold text-[var(--text-primary)]">
                    {teams.find((t) => t.id === selectedTeamId)?.name}
                  </h3>
                  <p className="text-sm text-[var(--text-muted)] mt-0.5">
                    {teams.find((t) => t.id === selectedTeamId)?.description || '暂无描述'}
                  </p>
                </div>
                <button
                  onClick={() => setSelectedTeamId(null)}
                  className="p-1 rounded text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--text-secondary)]"
                  aria-label="关闭详情面板"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              {/* Members in Team */}
              <div>
                <h4 className="text-sm font-medium text-[var(--text-primary)] mb-[var(--space-apple-sm)]">
                  团队成员 ({selectedTeamMembers.length})
                </h4>
                {selectedTeamMembers.length > 0 ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {selectedTeamMembers.map((m) => (
                      <div
                        key={m.userId}
                        className="flex items-center gap-2 p-2 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50"
                      >
                        <MiniAvatar name={m.displayName} size={28} />
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-[var(--text-primary)] truncate">{m.displayName}</p>
                          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] truncate">{m.email}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-sm text-[var(--text-muted)] py-4 text-center">
                    该团队暂无成员
                  </p>
                )}
              </div>
            </div>
          ) : (
            <div className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-8 text-center">
              <Users className="w-10 h-10 mx-auto text-[var(--text-muted)] dark:text-[var(--text-muted)] mb-[var(--space-apple-sm)]" />
              <p className="text-sm text-[var(--text-muted)]">选择一个团队查看详情</p>
            </div>
          )}
        </div>
      </div>

      {/* Create Modal */}
      <Modal
        open={showCreateModal}
        onClose={() => { setShowCreateModal(false); setFormName('') }}
        title={parentTeamId ? '创建子团队' : '创建新团队'}
        size="md"
      >
        <div className="space-y-[var(--space-apple-md)]">
          <div>
            <label htmlFor="team-name" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
              团队名称 <span className="text-[var(--color-error-text)]0">*</span>
            </label>
            <input
              id="team-name"
              type="text"
              value={formName}
              onChange={(e) => setFormName(e.target.value)}
              placeholder="例如：研发部"
              className="w-full px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)] focus:border-transparent"
              autoFocus
            />
          </div>
          <div>
            <label htmlFor="team-desc" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
              描述（可选）
            </label>
            <textarea
              id="team-desc"
              value={formDescription}
              onChange={(e) => setFormDescription(e.target.value)}
              placeholder="简要描述团队的职责..."
              rows={3}
              className="w-full px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] text-sm resize-none focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)] focus:border-transparent"
            />
          </div>
          <div className="flex justify-end gap-[var(--space-apple-sm)] pt-2">
            <button
              onClick={() => { setShowCreateModal(false); setFormName('') }}
              className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-sm)] transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleCreate}
              disabled={submitting || !formName.trim()}
              className={cn(
                'inline-flex items-center gap-2 px-[var(--space-apple-md)] py-2 text-sm rounded-[var(--radius-Apple-sm)] transition-colors',
                submitting || !formName.trim()
                  ? 'bg-[var(--border-color)] text-[var(--text-muted)] cursor-not-allowed'
                  : 'bg-secondary-container text-secondary-main hover:bg-secondary-container',
              )}
            >
              {submitting && <Loader2 className="w-4 h-4 animate-spin" />}
              创建
            </button>
          </div>
        </div>
      </Modal>

      {/* Edit Modal */}
      <Modal
        open={showEditModal}
        onClose={() => { setShowEditModal(false); setEditingTeam(null) }}
        title="编辑团队"
        size="md"
      >
        <div className="space-y-[var(--space-apple-md)]">
          <div>
            <label htmlFor="edit-team-name" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
              团队名称 <span className="text-[var(--color-error-text)]0">*</span>
            </label>
            <input
              id="edit-team-name"
              type="text"
              value={formName}
              onChange={(e) => setFormName(e.target.value)}
              className="w-full px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)] focus:border-transparent"
              autoFocus
            />
          </div>
          <div>
            <label htmlFor="edit-team-desc" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
              描述（可选）
            </label>
            <textarea
              id="edit-team-desc"
              value={formDescription}
              onChange={(e) => setFormDescription(e.target.value)}
              rows={3}
              className="w-full px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] text-sm resize-none focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)] focus:border-transparent"
            />
          </div>
          <div className="flex justify-end gap-[var(--space-apple-sm)] pt-2">
            <button
              onClick={() => { setShowEditModal(false); setEditingTeam(null) }}
              className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-sm)] transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleUpdate}
              disabled={submitting || !formName.trim()}
              className={cn(
                'inline-flex items-center gap-2 px-[var(--space-apple-md)] py-2 text-sm rounded-[var(--radius-Apple-sm)] transition-colors',
                submitting || !formName.trim()
                  ? 'bg-[var(--border-color)] text-[var(--text-muted)] cursor-not-allowed'
                  : 'bg-secondary-container text-secondary-main hover:bg-secondary-container',
              )}
            >
              {submitting && <Loader2 className="w-4 h-4 animate-spin" />}
              保存更改
            </button>
          </div>
        </div>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal
        open={showDeleteModal}
        onClose={() => { setShowDeleteModal(false); setDeletingTeam(null) }}
        title="删除团队"
        size="sm"
      >
        <div className="space-y-[var(--space-apple-md)]">
          <div className="rounded-[var(--radius-Apple-sm)] bg-[var(--color-error-container)] border border-[var(--color-error-border)] dark:border-[var(--color-error)] p-[var(--space-apple-sm)]">
            <p className="text-sm text-[var(--color-error-text)] dark:text-[var(--color-error-text)]">
              确定要删除团队 <strong>"{deletingTeam?.name}"</strong> 吗？此操作不可撤销。
            </p>
          </div>
          <div className="flex justify-end gap-[var(--space-apple-sm)] pt-2">
            <button
              onClick={() => { setShowDeleteModal(false); setDeletingTeam(null) }}
              className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-sm)] transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleDelete}
              disabled={submitting}
              className={cn(
                'px-[var(--space-apple-md)] py-2 text-sm rounded-[var(--radius-Apple-sm)] transition-colors',
                submitting
                  ? 'bg-[var(--border-color)] text-[var(--text-muted)] cursor-not-allowed'
                  : 'bg-[var(--color-error)] text-white hover:bg-[var(--color-error)]',
              )}
            >
              {submitting ? <Loader2 className="w-4 h-4 inline animate-spin mr-1" /> : null}
              确认删除
            </button>
          </div>
        </div>
      </Modal>
    </div>
  )
})

export default TeamsTab
